fn frame(t: i32) {
    let h: i32 = host::display::height();
    host::display::clear(0x000000);
    let mut n: i32 = 27;
    let mut steps: i32 = 0;
    let mut i: i32 = 0;
    while n != 1 {
        if i < 40 {
            let mut bh: i32 = n / 40;
            if bh < 1 { bh = 1; }
            host::display::fill_rect(8 + i * 10, h - 16 - bh, 8, bh, 0xff8800);
        }
        if n % 2 == 0 { n = n / 2; } else { n = n * 3 + 1; }
        steps = steps + 1;
        i = i + 1;
    }
    host::display::draw_string(8, 8, "COLLATZ 27 STEPS", 0x808080, 1);
    host::display::draw_number(8, 24, steps, 0xffffff, 2);
    host::display::present();
}
